package com.aditya.day13.delivery; import org.springframework.stereotype.Service; import java.util.*; @Service public class DeliveryService{public double distance(double a,double b,double c,double d){double p=Math.PI/180,x=(c-a)*p,y=(d-b)*p,h=Math.sin(x/2)*Math.sin(x/2)+Math.cos(a*p)*Math.cos(c*p)*Math.sin(y/2)*Math.sin(y/2);return 6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}public DeliveryPartner nearest(double lat,double lng,List<DeliveryPartner> ds){return ds.stream().min(Comparator.comparingDouble(x->distance(lat,lng,x.getLat(),x.getLng()))).orElse(null);}}